#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode *next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode *next) : val(x), next(next) {}
};
// test helpers: read "n v1 v2 ... vn" into a list, print a list
ListNode* readList() {
    int n; cin >> n;
    ListNode* h = nullptr; ListNode* t = nullptr;
    for (int i = 0; i < n; i++) {
        int x; cin >> x;
        ListNode* nd = new ListNode(x);
        if (!h) h = t = nd; else { t->next = nd; t = nd; }
    }
    return h;
}
void printList(ListNode* h) {
    if (!h) cout << "(empty)";
    while (h) { cout << h->val; if (h->next) cout << " -> "; h = h->next; }
    cout << "\n";
}

